import 'dart:convert';
import 'dart:math';
import 'package:cloud_functions/cloud_functions.dart';
import 'package:firebase_app_check/firebase_app_check.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';

const campusLeagueEnabled = false;

abstract class QuizGateway {
  Future<Map<String, dynamic>> call(String method, Map<String, dynamic> data);
  Future<Map<String, dynamic>> start(String poolId, {bool duel = false});
}
final quizGatewayProvider = Provider<QuizGateway>((ref) => FirebaseQuizGateway());
class FirebaseQuizGateway implements QuizGateway {
  Future<void>? _ready;
  Future<void> _initialize() async {
    if (kIsWeb || defaultTargetPlatform != TargetPlatform.android) {
      throw StateError('Campus League is available in the Android app.');
    }
    await FirebaseAppCheck.instance.activate(androidProvider: AndroidProvider.playIntegrity);
  }
  @override
  Future<Map<String, dynamic>> call(String method, Map<String, dynamic> data) async {
    if (!campusLeagueEnabled) throw StateError('Campus League is coming soon.');
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) throw StateError('Sign in to continue.');
    try { await (_ready ??= _initialize()); } catch (_) { _ready = null; rethrow; }
    if (FirebaseAuth.instance.currentUser?.uid != uid) throw StateError('Account changed. Reopen Campus League.');
    final result = await FirebaseFunctions.instanceFor(region: 'us-central1')
        .httpsCallable(method, options: HttpsCallableOptions(timeout: const Duration(seconds: 40))).call(data);
    if (FirebaseAuth.instance.currentUser?.uid != uid) throw StateError('Account changed. Reopen Campus League.');
    return Map<String, dynamic>.from(result.data as Map);
  }
  @override
  Future<Map<String, dynamic>> start(String poolId, {bool duel = false}) async {
    if (!campusLeagueEnabled) throw StateError('Campus League is coming soon.');
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) throw StateError('Sign in to continue.');
    final prefs = await SharedPreferences.getInstance();
    final key = 'hyzen_quiz_request_${uid}_${duel ? 'duel' : 'solo'}_$poolId';
    var request = prefs.getString(key);
    if (request == null) {
      request = base64Url.encode(List.generate(24, (_) => Random.secure().nextInt(256))).replaceAll('=', '');
      if (!await prefs.setString(key, request)) throw StateError('Could not save recovery information.');
    }
    final result = await call(duel ? 'createQuizDuel' : 'startQuiz', {'poolId': poolId, 'requestId': request});
    // Successful start IDs are recovered from the server lobby. Keep the same
    // request on every uncertain failure so retries cannot consume extra quota.
    await prefs.remove(key);
    return result;
  }
}
String quizError(Object error) {
  if (error is FirebaseFunctionsException) {
    return switch (error.message) {
      'feature_disabled' || 'policy_unavailable' => 'Campus League is not open yet. Please check again later.',
      'membership_required' => 'Your competition access needs administrator verification.',
      'cooldown' => 'Wait one hour after your last start before trying again.',
      'daily_limit' => 'You have used your three attempts for today.',
      'attempt_active' => 'Resume your current quiz or pending duel first.',
      'insufficient_questions' => 'There are not enough new questions for this quiz yet.',
      'revision_conflict' => 'Your answers changed on another device. Refresh to load the saved version.',
      'duel_unavailable' => 'This invitation is unavailable or has expired.',
      'invitation_limit' => 'You have used your three duel invitations for today.',
      'pool_changed' => 'This quiz changed. Cancel this invitation and create a new one.',
      _ => 'Campus League could not connect. Check your connection and retry.',
    };
  }
  return 'Could not complete this request. Check your connection and retry.';
}

