import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'quiz_gateway.dart';

class QuizScreen extends ConsumerStatefulWidget {
  const QuizScreen({super.key});
  @override
  ConsumerState<QuizScreen> createState() => _QuizScreenState();
}
class _QuizScreenState extends ConsumerState<QuizScreen> {
  Map<String, dynamic>? lobby, attempt, invitation;
  String? error;
  bool busy = false;
  Timer? ticker;
  final elapsed = Stopwatch();
  final code = TextEditingController();
  int seconds = 0;
  QuizGateway get api => ref.read(quizGatewayProvider);
  @override
  void initState() {
    super.initState();
    Future.microtask(load);
    ticker = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted) return;
      setState(() => seconds++);
      if (busy) return;
      if (attempt != null && attempt!['state'] == 'active' && remaining <= 0) {
        refreshAttempt();
      } else if (seconds % 5 == 0 && invitation?['state'] == 'waiting') {
        refreshInvitation();
      } else if (seconds % 5 == 0 && attempt?['state'] == 'submitted' && attempt?['duelState'] == 'active') {
        refreshAttempt();
      }
    });
  }
  @override
  void dispose() { ticker?.cancel(); elapsed.stop(); code.dispose(); super.dispose(); }
  int get remaining {
    if (attempt == null) return 0;
    return (((attempt!['deadline'] as num) - (attempt!['serverNow'] as num) - elapsed.elapsedMilliseconds) / 1000).ceil().clamp(0, 86400).toInt();
  }
  Future<void> run(Future<void> Function() task) async {
    if (!mounted || busy) return;
    setState(() {busy = true; error = null;});
    try { await task(); } catch (e) { if (mounted) setState(() => error = quizError(e)); }
    finally { if (mounted) setState(() => busy = false); }
  }
  void receive(Map<String, dynamic> value) {
    if (!mounted) return;
    setState(() {attempt = value; invitation = null;}); elapsed.reset(); elapsed.start();
  }
  Future<void> load() => run(() async {
    final value = await api.call('quizLobby', {});
    if (mounted) setState(() {lobby = value; attempt = null; invitation = null;});
  });
  Future<void> refreshAttempt() => run(() async {receive(await api.call('getQuiz', {'attemptId': attempt!['attemptId']}));});
  Future<void> refreshInvitation() => run(() async {
    final value = await api.call('getQuizDuel', {'code': invitation!['code']});
    if (!mounted) return;
    if (value.containsKey('attemptId')) {receive(value);} else {setState(() => invitation = {...invitation!, ...value});}
  });
  Future<void> start(String pool, bool duel) => run(() async {
    final value = await api.start(pool, duel: duel);
    if (!mounted) return;
    if (duel) {setState(() {invitation = value; attempt = null;});} else {receive(value);}
  });
  Future<void> answer(String id, String option) => run(() async {
    final selected = Map<String, dynamic>.from(attempt!['answers'] as Map)..[id] = option;
    receive(await api.call('saveQuiz', {'attemptId': attempt!['attemptId'], 'revision': attempt!['revision'], 'answers': selected}));
  });
  @override
  Widget build(BuildContext context) {
    final a = attempt;
    return Scaffold(
      appBar: AppBar(title: const Text('Campus League'), actions: [IconButton(tooltip: 'Refresh', onPressed: busy ? null : a != null ? refreshAttempt : invitation != null ? refreshInvitation : load, icon: const Icon(Icons.refresh))]),
      body: SafeArea(child: ListView(padding: const EdgeInsets.all(20), children: [
        if (busy) const LinearProgressIndicator(),
        if (error != null) Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(children: [Text(error!), TextButton(onPressed: busy ? null : a != null ? refreshAttempt : invitation != null ? refreshInvitation : load, child: const Text('Retry'))]))),
        if (a != null) ...attemptWidgets(a)
        else if (invitation != null) ...invitationWidgets()
        else if (lobby != null) ...lobbyWidgets()
        else if (!busy && error == null) const Text('No quiz information available.'),
      ])),
    );
  }
  List<Widget> lobbyWidgets() {
    final pools = lobby!['pools'] as List;
    return [
      Text('Practice. Challenge. Improve.', style: Theme.of(context).textTheme.headlineSmall),
      const SizedBox(height: 12),
      Text('${lobby!['attemptsToday']} of 3 daily attempts used'),
      const Text('One point per correct answer. No negative marking. Started quizzes count toward your daily limit; wait one hour between starts. Duels share this limit.'),
      const SizedBox(height: 16),
      if (lobby!['lastAttemptId'] != null) OutlinedButton(onPressed: busy ? null : () => run(() async {receive(await api.call('getQuiz', {'attemptId': lobby!['lastAttemptId']}));}), child: const Text('Open last quiz / result')),
      if (lobby!['lastDuelCode'] != null) OutlinedButton(onPressed: busy ? null : () => run(() async {
        final value = await api.call('getQuizDuel', {'code': lobby!['lastDuelCode']});
        if (!mounted) return;
        if (value.containsKey('attemptId')) {receive(value);} else {setState(() => invitation = {'code': lobby!['lastDuelCode'], ...value});}
      }), child: const Text('Open last duel')),
      for (final raw in pools) Builder(builder: (context) {
        final p = Map<String, dynamic>.from(raw as Map);
        return Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(p['title'] as String, style: Theme.of(context).textTheme.titleLarge),
          Text('${p['questionCount']} questions · ${p['durationSeconds']} seconds'),
          Wrap(spacing: 12, children: [FilledButton(onPressed: busy ? null : () => start(p['id'] as String, false), child: const Text('Start quiz')),
            OutlinedButton(onPressed: busy ? null : () => start(p['id'] as String, true), child: const Text('Create duel'))]),
        ])));
      }),
      if (pools.isEmpty) const Padding(padding: EdgeInsets.symmetric(vertical: 16), child: Text('No quizzes are open for your verified year yet.')),
      const Divider(height: 32),
      Text('Join a friend', style: Theme.of(context).textTheme.titleLarge),
      const Text('Joining starts the same timed quiz for both players and uses one attempt for each.'),
      TextField(controller: code, maxLength: 64, decoration: const InputDecoration(labelText: 'Duel invitation code')),
      FilledButton(onPressed: busy ? null : () => run(() async {receive(await api.call('joinQuizDuel', {'code': code.text.trim()}));}), child: const Text('Accept and start duel')),
    ];
  }
  List<Widget> invitationWidgets() {
    final d = invitation!;
    final waiting = d['state'] == 'waiting';
    return [
      Text(waiting ? 'Invite your opponent' : 'Invitation ${d['state']}', style: Theme.of(context).textTheme.headlineSmall),
      if (waiting) ...[
        const Text('The timer starts for both players when your opponent accepts. Stay on this screen. This invitation expires after ten minutes or when the quiz closes.'),
        SelectableText(d['code'] as String),
        OutlinedButton(onPressed: () => Clipboard.setData(ClipboardData(text: d['code'] as String)), child: const Text('Copy invitation code')),
        OutlinedButton(onPressed: busy ? null : () => run(() async {
          await api.call('cancelQuizDuel', {'code': d['code']});
          if (mounted) setState(() => invitation = {...d, 'state': 'cancelled'});
        }), child: const Text('Cancel invitation')),
      ],
      TextButton(onPressed: busy ? null : load, child: const Text('Back to quizzes')),
    ];
  }
  List<Widget> attemptWidgets(Map<String, dynamic> a) {
    final finished = a['state'] == 'submitted';
    final selected = Map<String, dynamic>.from(a['answers'] as Map);
    return [
      Text(finished ? 'Quiz complete' : '$remaining seconds remaining', style: Theme.of(context).textTheme.headlineSmall),
      if (!finished) const Text('Each answer is saved to the server. Keep your connection active. The server deadline determines which answers count.'),
      if (finished) ...[
        Text('${(a['result'] as Map)['correct']} / ${(a['result'] as Map)['total']} correct'),
        if (a['duelResult'] != null) Text('Duel: ${a['duelResult']}')
        else if (a['duelState'] == 'active') const Text('Waiting for your opponent to finish or the timer to end.'),
        TextButton(onPressed: busy ? null : load, child: const Text('Back to quizzes')),
      ],
      for (final raw in a['questions'] as List) Builder(builder: (context) {
        final q = Map<String, dynamic>.from(raw as Map), options = Map<String, dynamic>.from((raw as Map)['options'] as Map);
        return Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(q['stem'] as String, style: Theme.of(context).textTheme.titleMedium),
          for (final entry in options.entries) Semantics(selected: selected[q['id']] == entry.key, button: true, child: ListTile(contentPadding: EdgeInsets.zero, title: Text(entry.value as String), leading: Icon(selected[q['id']] == entry.key ? Icons.radio_button_checked : Icons.radio_button_unchecked),
            enabled: !busy && !finished && remaining > 0, onTap: busy || finished || remaining <= 0 ? null : () => answer(q['id'] as String, entry.key))),
        ])));
      }),
      if (!finished) FilledButton(onPressed: busy ? null : () => run(() async {
        receive(await api.call('submitQuiz', {'attemptId': a['attemptId'], 'revision': a['revision'], 'answers': selected}));
      }), child: const Text('Submit saved answers')),
    ];
  }
}

