import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/features/quiz/quiz_gateway.dart';
import 'package:hyzen_pharmd/features/quiz/quiz_screen.dart';

class FixtureGateway implements QuizGateway {
  bool failLobby = false, failSave = false;
  final calls = <(String, Map<String, dynamic>)>[];
  Map<String, dynamic> attempt = {'attemptId': 'fixture-attempt', 'state': 'active', 'serverNow': 1000, 'deadline': 61000, 'revision': 0, 'answers': <String, dynamic>{}, 'questions': [{'id':'q1','stem':'Which fixture answer?','options':{'A':'Alpha','B':'Beta','C':'Gamma','D':'Delta'}}]};
  @override
  Future<Map<String, dynamic>> call(String method, Map<String, dynamic> data) async {
    calls.add((method, Map.of(data)));
    if (method == 'quizLobby') {
      if (failLobby) throw StateError('offline');
      return {'pools': [{'id':'fixture','title':'Practice fixture','questionCount':1,'durationSeconds':60}], 'attemptsToday':0};
    }
    if (method == 'saveQuiz') {
      if (failSave) throw StateError('offline');
      attempt = {...attempt, 'revision': 1, 'answers': data['answers']};
    }
    if (method == 'submitQuiz') attempt = {...attempt, 'state':'submitted', 'result':{'correct':1,'total':1}};
    if (method == 'getQuizDuel') return {'state':'waiting','serverNow':1000,'expiresAt':601000};
    return Map.of(attempt);
  }
  @override
  Future<Map<String, dynamic>> start(String poolId, {bool duel = false}) async {
    calls.add((duel ? 'createQuizDuel' : 'startQuiz', {'poolId':poolId}));
    return duel ? {'code':'a'*64,'state':'waiting','expiresAt':601000} : Map.of(attempt);
  }
}
void main() {
  Future<void> open(WidgetTester tester, FixtureGateway gateway) async {
    await tester.pumpWidget(ProviderScope(overrides:[quizGatewayProvider.overrideWithValue(gateway)],child:const MaterialApp(home:QuizScreen())));
    await tester.pumpAndSettle();
  }
  testWidgets('lobby failure shows retry without fake quizzes', (tester) async {
    final g=FixtureGateway()..failLobby=true;await open(tester,g);
    expect(find.text('Retry'),findsOneWidget);expect(find.text('Start quiz'),findsNothing);
    g.failLobby=false;await tester.tap(find.text('Retry'));await tester.pumpAndSettle();
    expect(find.text('Practice fixture'),findsOneWidget);
    await tester.pumpWidget(const SizedBox());
  });
  testWidgets('answer saves through server revision and submit uses saved payload', (tester) async {
    final g=FixtureGateway();await open(tester,g);await tester.tap(find.text('Start quiz'));await tester.pumpAndSettle();
    await tester.tap(find.text('Beta'));await tester.pumpAndSettle();
    final save=g.calls.firstWhere((v)=>v.$1=='saveQuiz').$2;
    expect(save['revision'],0);expect(save['answers'],{'q1':'B'});
    await tester.ensureVisible(find.text('Submit saved answers'));await tester.tap(find.text('Submit saved answers'));await tester.pumpAndSettle();
    expect(g.calls.firstWhere((v)=>v.$1=='submitQuiz').$2['revision'],1);expect(find.text('1 / 1 correct'),findsOneWidget);
    await tester.pumpWidget(const SizedBox());
  });
  testWidgets('failed save retains confirmed answers and presents recovery', (tester) async {
    final g=FixtureGateway()..failSave=true;await open(tester,g);await tester.tap(find.text('Start quiz'));await tester.pumpAndSettle();
    await tester.tap(find.text('Beta'));await tester.pumpAndSettle();
    expect(find.text('Retry'),findsOneWidget);expect(g.attempt['answers'],isEmpty);
    await tester.pumpWidget(const SizedBox());
  });
  testWidgets('duel waiting screen shows code without premature questions', (tester) async {
    final g=FixtureGateway();await open(tester,g);await tester.tap(find.text('Create duel'));await tester.pumpAndSettle();
    expect(find.text('Copy invitation code'),findsOneWidget);expect(find.text('Which fixture answer?'),findsNothing);
    await tester.pumpWidget(const SizedBox());
  });
}

