import 'dart:convert';
import 'package:crypto/crypto.dart';
import 'package:cloud_functions/cloud_functions.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../quiz_gateway.dart';

String _requestId(Map<String, dynamic> data) => sha256.convert(utf8.encode(jsonEncode(data))).toString();
String _adminError(Object error) {
  if (error is FirebaseFunctionsException) {
    if (error.code == 'permission-denied') return 'Question Bank access is not enabled for this account.';
    if (error.code == 'unauthenticated') return 'Sign in again to continue.';
    if (error.message == 'invalid_csv') {
      final details = error.details;
      final line = details is Map ? details['line'] : null;
      final field = details is Map ? details['field'] : null;
      return 'CSV validation failed${line is int ? ' at line $line' : ''}${field is String ? ' ($field)' : ''}. Check the template and try again.';
    }
    if (['feature_disabled', 'taxonomy_unavailable'].contains(error.message)) return 'Question Bank setup is not complete. Approved subjects and topics are required.';
    if (['publication_conflict', 'confirmation_mismatch', 'taxonomy_changed'].contains(error.message)) return 'This review has changed. Close it and review the latest question before confirming.';
    if (error.message == 'batch_expired') return 'This preview expired. Generate a new preview.';
    if (error.message == 'revision_conflict') return 'A question ID already exists. Existing revisions were not overwritten.';
  }
  return 'Could not confirm the request. Check your connection and retry the same action.';
}

class QuestionBankScreen extends ConsumerStatefulWidget {
  const QuestionBankScreen({super.key});
  @override
  ConsumerState<QuestionBankScreen> createState() => _QuestionBankState();
}
class _QuestionBankState extends ConsumerState<QuestionBankScreen> {
  final _csv = TextEditingController();
  List<Map<String, dynamic>> _items = [];
  Map<String, dynamic>? _review, _preview;
  String? _cursor, _error, _notice;
  bool _busy = false, _acknowledged = false, _importing = false, _loaded = false;
  Future<void> _run(Future<void> Function() action) async {
    if (_busy) return;
    setState(() { _busy = true; _error = null; _notice = null; });
    try { await action(); } catch (error) {
      if (mounted) setState(() => _error = _adminError(error));
    } finally { if (mounted) setState(() => _busy = false); }
  }
  Future<Map<String, dynamic>> _call(String method, Map<String, dynamic> data) => ref.read(quizGatewayProvider).call(method, data);
  @override
  void initState() { super.initState(); Future.microtask(() { if (mounted) _load(); }); }
  @override
  void dispose() { _csv.dispose(); super.dispose(); }
  Future<void> _load({bool more = false}) => _run(() async {
    final result = await _call('listQuizQuestions', {if (more && _cursor != null) 'after':_cursor});
    if (!mounted) return;
    final items = (result['items'] as List).map((v) => Map<String, dynamic>.from(v as Map)).toList();
    setState(() { _items = more ? [..._items, ...items] : items; _cursor = result['nextCursor'] as String?; _loaded = true; });
  });
  Future<void> _open(String revision) => _run(() async {
    final result = await _call('reviewQuizQuestion', {'revision':revision});
    if (mounted) setState(() { _review = result; _acknowledged = false; });
  });
  Future<void> _publish() => _run(() async {
    final r = _review!;
    final q = Map<String, dynamic>.from(r['question'] as Map);
    final data = <String, dynamic>{'revision':q['revision'],'contentHash':r['contentHash'],
      'enabled':r['enabled'] != true,'reviewed':true,'expectedVersion':r['publicationVersion']};
    data['requestId'] = _requestId(data);
    final result = await _call('setQuizPublication', data);
    if (mounted) setState(() { _review = null; _acknowledged = false;
      _notice = result['enabled'] == true ? 'Question published for future quizzes.' : 'Question withdrawn from future quizzes. Existing attempts are unchanged.'; });
  });
  Future<void> _pickCsv() => _run(() async {
    final files = await const MethodChannel('com.hyzen.pharmd/csv_files').invokeListMethod<dynamic>('pickCsvFiles');
    if (!mounted || files == null || files.isEmpty) return;
    if (files.length != 1) { setState(() => _error = 'Choose one CSV file at a time.'); return; }
    final file = files.single;
    if (file is! Map || file['bytes'] is! List) throw const FormatException('File could not be read.');
    final bytes = List<int>.from(file['bytes'] as List);
    if (bytes.length > 256 * 1024) { setState(() => _error = 'CSV must be no larger than 256 KB.'); return; }
    final text = utf8.decode(bytes, allowMalformed:false);
    setState(() { _csv.text = text; _preview = null; _notice = 'CSV loaded. Validate it before confirming the import.'; });
  });
  Future<void> _previewCsv() => _run(() async {
    if (utf8.encode(_csv.text).length > 256 * 1024) {
      setState(() => _error = 'CSV must be no larger than 256 KB.'); return;
    }
    final result = await _call('previewQuizCsv', {'csv':_csv.text});
    if (mounted) setState(() => _preview = result);
  });
  Future<void> _commitCsv() => _run(() async {
    final p = _preview!;
    final data = <String,dynamic>{'batchId':p['batchId'],'checksum':p['checksum']};
    data['idempotencyKey'] = _requestId(data);
    final result = await _call('commitQuizCsv', data);
    if (mounted) setState(() { _preview = null; _csv.clear(); _importing = false;
      _loaded = false; _items = []; _cursor = null;
      _notice = '${result['imported']} draft questions imported. Refresh to review and publish them.'; });
  });
  @override
  Widget build(BuildContext context) {
    final review = _review;
    final q = review == null ? null : Map<String,dynamic>.from(review['question'] as Map);
    return Scaffold(
      appBar: AppBar(title: const Text('Question Bank')),
      body: SafeArea(child: ListView(padding: const EdgeInsets.all(20), children: [
        Text('Campus League', style: Theme.of(context).textTheme.labelLarge),
        const SizedBox(height:8),
        const Text('Import draft questions, check the answers, then approve publication.'),
        const SizedBox(height:16),
        if (_busy) const LinearProgressIndicator(),
        if (_error != null) Padding(padding: const EdgeInsets.symmetric(vertical:12), child: Text(_error!, semanticsLabel:'Error: $_error', style: TextStyle(color:Theme.of(context).colorScheme.error))),
        if (_notice != null) Padding(padding: const EdgeInsets.symmetric(vertical:12), child: Text(_notice!)),
        if (q != null) ...[
          Text('${q['subject']} / ${q['topic']} · Year ${q['professionalYear']}'),
          const SizedBox(height:12),
          Text(q['stem'] as String, style: Theme.of(context).textTheme.titleLarge),
          const SizedBox(height:12),
          for (final letter in ['A','B','C','D']) Card(child: ListTile(
            leading: Icon(q['correctOption'] == letter ? Icons.check_circle : Icons.circle_outlined),
            title: Text('$letter. ${(q['options'] as Map)[letter]}'),
            subtitle: q['correctOption'] == letter ? const Text('Correct answer') : null)),
          const SizedBox(height:8), Text('Explanation: ${q['explanation']}'),
          const SizedBox(height:8), Text(review!['enabled'] == true ? 'Currently published' : 'Currently unpublished'),
          CheckboxListTile(contentPadding: EdgeInsets.zero, title: const Text('I reviewed the question and answer and confirm this change.'),
            value:_acknowledged,onChanged:_busy ? null : (v)=>setState(()=>_acknowledged=v??false)),
          FilledButton(onPressed:_busy || !_acknowledged ? null : _publish,
            child:Text(review['enabled'] == true ? 'Withdraw publication' : 'Publish question')),
          TextButton(onPressed:_busy ? null : ()=>setState(() { _review=null; _error=null; }),child:const Text('Close review')),
        ] else if (_importing) ...[
          const Text('CSV import · maximum 200 questions / 256 KB'),
          const SizedBox(height:8),
          const SelectableText('question_id,professional_year,subject,topic,question,option_a,option_b,option_c,option_d,correct_option'),
          const SizedBox(height:8),
          const Text('Use approved subject/topic names. Optional columns: explanation, difficulty, status. Imports always create unpublished drafts.'),
          const SizedBox(height:12),
          OutlinedButton.icon(onPressed:_busy || _preview != null ? null : _pickCsv,icon:const Icon(Icons.file_open_outlined),label:const Text('Choose CSV file')),
          TextField(controller:_csv,enabled:!_busy && _preview==null,minLines:5,maxLines:10,maxLength:262144,
            decoration:const InputDecoration(labelText:'Paste CSV',border:OutlineInputBorder())),
          if (_preview == null) FilledButton(onPressed:_busy ? null : _previewCsv,child:const Text('Validate CSV')),
          if (_preview != null) ...[
            Text('${_preview!['rowCount']} valid draft questions. Preview expires: ${_preview!['expiresAt']}'),
            FilledButton(onPressed:_busy ? null : _commitCsv,child:const Text('Confirm draft import')),
            TextButton(onPressed:_busy ? null : ()=>setState(()=>_preview=null),child:const Text('Edit CSV')),
          ],
          TextButton(onPressed:_busy ? null : ()=>setState(() { _importing=false; _preview=null; _error=null; }),child:const Text('Back to questions')),
        ] else ...[
          Wrap(spacing:8,children:[
            FilledButton.icon(onPressed:_busy ? null : ()=>setState(() { _importing=true; _error=null; }),icon:const Icon(Icons.upload_file),label:const Text('Import CSV')),
            OutlinedButton.icon(onPressed:_busy ? null : ()=>_load(),icon:const Icon(Icons.refresh),label:const Text('Refresh questions')),
          ]),
          const SizedBox(height:16),
          if (_loaded && _items.isEmpty) const Text('No questions imported yet.'),
          for (final item in _items) Card(child:ListTile(
            title:Text(item['stem'] as String,maxLines:3,overflow:TextOverflow.ellipsis),
            subtitle:Text('${item['subject']} · ${item['topic']} · Year ${item['professionalYear']}'),
            trailing:const Icon(Icons.chevron_right),onTap:_busy ? null : ()=>_open(item['revision'] as String))),
          if (_cursor != null) OutlinedButton(onPressed:_busy ? null : ()=>_load(more:true),child:const Text('Load more')),
        ],
      ])),
    );
  }
}

