import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/services.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/features/quiz/quiz_gateway.dart';
import 'package:hyzen_pharmd/features/quiz/admin/question_bank_screen.dart';
class AdminFixture implements QuizGateway {
  bool failList=false, failPublish=false, failImport=false;
  final calls=<(String,Map<String,dynamic>)>[];
  @override
  Future<Map<String,dynamic>> start(String poolId,{bool duel=false})=>throw UnimplementedError();
  @override
  Future<Map<String,dynamic>> call(String method,Map<String,dynamic> data) async {
    calls.add((method,Map.of(data)));
    switch(method) {
      case 'listQuizQuestions':
        if(failList) throw StateError('offline');
        return {'items':[{'revision':'fixture__v1','stem':'Fixture question?','subject':'Fixture','topic':'Synthetic','professionalYear':1}],'nextCursor':null};
      case 'reviewQuizQuestion':
        return {'question':{'revision':'fixture__v1','stem':'Fixture question?','subject':'Fixture','topic':'Synthetic','professionalYear':1,'options':{'A':'One','B':'Two','C':'Three','D':'Four'},'correctOption':'B','explanation':'Fixture explanation'},'contentHash':'a'*64,'enabled':false,'publicationVersion':0};
      case 'setQuizPublication':
        if(failPublish) throw StateError('offline');
        return {'enabled':true,'version':1};
      case 'previewQuizCsv':
        return {'rowCount':1,'batchId':'fixture-batch','checksum':'b'*64,'expiresAt':'2026-10-26T12:00:00Z'};
      case 'commitQuizCsv':
        if(failImport) throw StateError('offline');
        return {'imported':1};
      default:throw StateError(method);
    }
  }
}
void main() {
  Future<void> open(WidgetTester tester,AdminFixture gateway) async {
    await tester.pumpWidget(ProviderScope(overrides:[quizGatewayProvider.overrideWithValue(gateway)],child:const MaterialApp(home:QuestionBankScreen())));
    await tester.pumpAndSettle();
  }
  Future<void> tap(WidgetTester tester,String label) async {
    await tester.ensureVisible(find.text(label));await tester.tap(find.text(label));await tester.pumpAndSettle();
  }
  testWidgets('failed question list offers refresh without a fake empty success',(tester) async {
    final g=AdminFixture()..failList=true;await open(tester,g);
    expect(find.text('No questions imported yet.'),findsNothing);
    expect(find.textContaining('Could not confirm'),findsOneWidget);
    g.failList=false;await tap(tester,'Refresh questions');expect(find.text('Fixture question?'),findsOneWidget);
  });
  testWidgets('publication requires review acknowledgement and sends exact version and digest',(tester) async {
    final g=AdminFixture();await open(tester,g);await tap(tester,'Fixture question?');
    expect(find.text('Correct answer'),findsOneWidget);
    final button=find.widgetWithText(FilledButton,'Publish question');
    await tester.scrollUntilVisible(button,200);
    await tester.pumpAndSettle();
    expect(tester.widget<FilledButton>(button).onPressed,isNull);
    await tap(tester,'I reviewed the question and answer and confirm this change.');
    await tap(tester,'Publish question');
    final data=g.calls.singleWhere((x)=>x.$1=='setQuizPublication').$2;
    expect(data['contentHash'],'a'*64);expect(data['expectedVersion'],0);expect(data['reviewed'],true);
    expect(find.text('Question published for future quizzes.'),findsOneWidget);
  });
  testWidgets('uncertain publication retries exactly the same operation',(tester) async {
    final g=AdminFixture()..failPublish=true;await open(tester,g);await tap(tester,'Fixture question?');
    await tap(tester,'I reviewed the question and answer and confirm this change.');
    await tap(tester,'Publish question');g.failPublish=false;await tap(tester,'Publish question');
    final requests=g.calls.where((x)=>x.$1=='setQuizPublication').toList();
    expect(requests.length,2);expect(requests[0].$2,requests[1].$2);
  });
  testWidgets('CSV validation never commits until explicit confirmation; uncertain import is retryable',(tester) async {
    final g=AdminFixture()..failImport=true;await open(tester,g);await tap(tester,'Import CSV');
    await tester.enterText(find.byType(TextField),'fixture CSV');await tap(tester,'Validate CSV');
    expect(g.calls.where((x)=>x.$1=='commitQuizCsv'),isEmpty);
    expect(tester.widget<TextField>(find.byType(TextField)).enabled,false);
    await tap(tester,'Confirm draft import');g.failImport=false;await tap(tester,'Confirm draft import');
    final requests=g.calls.where((x)=>x.$1=='commitQuizCsv').toList();
    expect(requests[0].$2,requests[1].$2);
    expect(find.textContaining('1 draft questions imported'),findsOneWidget);
  });
  testWidgets('device picker loads CSV locally without uploading or committing',(tester) async {
    const channel=MethodChannel('com.hyzen.pharmd/csv_files');
    tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(channel,(call) async => [{'name':'fixture.csv','bytes':Uint8List.fromList(utf8.encode('fixture CSV'))}]);
    addTearDown(()=>tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(channel,null));
    final g=AdminFixture();await open(tester,g);await tap(tester,'Import CSV');await tap(tester,'Choose CSV file');
    expect(tester.widget<TextField>(find.byType(TextField)).controller!.text,'fixture CSV');
    expect(g.calls.where((x)=>x.$1=='previewQuizCsv' || x.$1=='commitQuizCsv'),isEmpty);
  });

}

